"""Lightweight signatures/structure checks for files generated by the Blender pipeline.

These checks catch missing/truncated/mislabeled outputs; they do not prove the
geometry, image pixels or target-application import are correct.
"""
from __future__ import annotations

import json
import struct
import zlib
from pathlib import Path


class InvalidOutput(ValueError):
    """A generated file is missing, malformed or inconsistent."""


def validate_file(path: Path, kind: str, resolution: int | None = None) -> None:
    path = Path(path)
    if not path.is_file():
        raise InvalidOutput(f"Missing output: {path}")
    size = path.stat().st_size
    if size < 12:
        raise InvalidOutput(f"Output is too small: {path} ({size} bytes)")
    with path.open('rb') as file:
        header = file.read(64)
        if kind == 'blend':
            if not header.startswith(b'BLENDER'):
                raise InvalidOutput(f"Not a Blender .blend file: {path}")
        elif kind == 'glb':
            if size < 20 or header[:4] != b'glTF':
                raise InvalidOutput(f"Not a binary GLB file: {path}")
            _, version, declared_length = struct.unpack_from('<4sII', header)
            if version != 2 or declared_length != size:
                raise InvalidOutput(f"Invalid GLB version/length: {path}")
            json_len, chunk_type = struct.unpack_from('<I4s', header, 12)
            if chunk_type != b'JSON' or json_len == 0 or json_len % 4 or json_len + 20 > size:
                raise InvalidOutput(f"Invalid GLB JSON chunk: {path}")
            file.seek(20)
            try:
                payload = json.loads(file.read(json_len).decode('utf-8'))
            except (ValueError, UnicodeDecodeError) as exc:
                raise InvalidOutput(f"Malformed GLB JSON: {path}") from exc
            if (not isinstance(payload, dict) or 'asset' not in payload or 'scenes' not in payload
                    or not isinstance(payload.get('meshes'), list) or not payload['meshes']):
                raise InvalidOutput(f"GLB missing asset/scenes/mesh data: {path}")
        elif kind == 'fbx':
            if not (header.startswith(b'Kaydara FBX Binary  \x00\x1a\x00') or
                    header.lstrip().startswith(b'; FBX')):
                raise InvalidOutput(f"Not a recognized FBX file: {path}")
        elif kind == 'png':
            if size < 45 or header[:8] != b'\x89PNG\r\n\x1a\n':
                raise InvalidOutput(f"Not a PNG image: {path}")
            if header[12:16] != b'IHDR' or struct.unpack_from('>I', header, 8)[0] != 13:
                raise InvalidOutput(f"PNG missing valid IHDR: {path}")
            width, height = struct.unpack_from('>II', header, 16)
            if width == 0 or height == 0 or (resolution and (width, height) != (resolution, resolution)):
                raise InvalidOutput(f"Unexpected PNG dimensions {width}x{height}: {path}")
            crc = struct.unpack_from('>I', header, 29)[0]
            if zlib.crc32(header[12:29]) != crc:
                raise InvalidOutput(f"Invalid PNG header checksum: {path}")
        else:
            raise ValueError(f"Unsupported output type: {kind}")
